CASE LOWER(a.type)
  WHEN 'meeting' THEN #{model.meetingWeight}
  WHEN 'call' THEN #{model.callWeight}
  WHEN 'email' THEN #{model.emailWeight}
  ELSE #{model.otherActivityWeight}
END

SELECT a.person_id AS entity_id, 'activity' AS source_type, a.id AS source_id, AS interaction_type, a.timestamp AS touched_at, AS weight FROM activity a WHERE a.workspace_id = #{workspaceId} AND a.person_id IS NOT NULL
AND a.id NOT IN
#{id}
UNION ALL SELECT n.person_id AS entity_id, 'note' AS source_type, n.id AS source_id, 'workspace-note' AS interaction_type, n.created_at AS touched_at, #{model.noteWeight} AS weight FROM note n WHERE n.workspace_id = #{workspaceId} AND n.visibility = 'workspace' AND n.person_id IS NOT NULL
AND n.id NOT IN
#{id}
UNION ALL SELECT t.person_id AS entity_id, 'task' AS source_type, t.id AS source_id, 'task' AS interaction_type, t.created_at AS touched_at, #{model.taskWeight} AS weight FROM task t WHERE t.workspace_id = #{workspaceId} AND t.person_id IS NOT NULL
AND t.id NOT IN
#{id}

