UPDATE person
name = #{name}, email = #{email}, phone = #{phone}, title = #{title}, company_id = #{company.id}NULL,
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE person
SET owner_id = #{ownerId,jdbcType=INTEGER}
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.select:
SELECT id FROM person
