FOR UPDATE

mapper.update:
UPDATE person SET image_url = #{imageUrl}
WHERE workspace_id = #{workspaceId} AND id = #{id}
  AND image_url <=> #{currentImageUrl}

UPDATE person
risk_excluded = #{riskExcluded}, intro_excluded = #{introExcluded},
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE person
SET lead_source = #{source,jdbcType=VARCHAR},
    lead_source_detail = #{detail,jdbcType=VARCHAR},
    referrer_person_id = #{referrerPersonId,jdbcType=INTEGER}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE person
SET lifecycle_stage = #{stage,jdbcType=VARCHAR},
    lifecycle_changed_at = #{changedAt},
    disqualified_reason = #{reason,jdbcType=VARCHAR},
    qualification_notes = #{notes,jdbcType=VARCHAR}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE person
SET first_responded_at = #{respondedAt}
WHERE workspace_id = #{workspaceId} AND id = #{id}
  AND first_response_due_at IS NOT NULL
  AND first_responded_at IS NULL

UPDATE person
SET first_response_breached_at = #{breachedAt}
WHERE workspace_id = #{workspaceId} AND id = #{id}
  AND archived_at IS NULL
  AND suspended_at IS NULL
  AND provision_ceased_at IS NULL
  AND first_response_due_at IS NOT NULL
  AND first_response_due_at <= #{breachedAt}
  AND first_responded_at IS NULL
  AND first_response_breached_at IS NULL

mapper.insert:
INSERT IGNORE INTO person_tag (person_id, tag_id)
SELECT p.id, #{tagId}
FROM person p
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}

INSERT IGNORE INTO person_tag (person_id, tag_id)
SELECT p.id, t.id
FROM person p
JOIN tag t ON t.id IN

  #{tagId}

WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId} AND t.workspace_id = #{workspaceId}
